    stats: [["14","Old URLs redirected"],["0","Invented facts"],["N–X","Classes covered"]],
    quote: null,
    num: "10", name: "Pinnacle World School", category: "Education · CBSE", year: "2026",
    liveUrl: "https://www.pinnacleworldschool.co.in",
    domain: "pinnacleworldschool.co.in",
    headlineTail: "— CBSE school website, Kangra",
    updated: "2026-09-29",
    stackLine: "Next.js 16 · React 19 · TypeScript · Vercel",
